import { useCallback } from 'react';

import {
  BrandAvatarList,
  ChartLegend,
  ChartLegendItem,
  ComparisonLine,
  Waterfall,
} from 'components';
import {
  VALUE_CREATION_TREND_COLORS,
  WATERFALL_COLORS,
} from 'pages/pillars/ValueCreation/PerformanceTool/constants';
import { WaterfallData } from 'pages/pillars/ValueCreation/PerformanceTool/types';

import {
  StyledChartContainer,
  StyledComparisonLineWrapper,
  StyledLegendContainer,
  StyledWaterfallContainer,
} from './WaterfallContent.styles';

export interface WaterfallContentProps {
  chartData: WaterfallData | undefined;
  disabledIndexes: number[];
  legendItems: ChartLegendItem[];
  shouldShowLegend: boolean;
  onBarClick: (index: number | null) => void;
}

export const WaterfallContent = ({
  chartData,
  disabledIndexes,
  legendItems,
  shouldShowLegend,
  onBarClick,
}: WaterfallContentProps) => {
  const renderLegend = useCallback(() => {
    const brandsData = chartData?.images?.data?.map((brand, index) => {
      const { mainBrand, ...rest } = brand;
      const labelEntry = chartData?.labels?.[index];
      const country = Array.isArray(labelEntry) ? labelEntry[1] : undefined;

      return {
        ...rest,
        index,
        description: country || undefined,
        ...(mainBrand?.src ? { mainBrand } : {}),
      };
    });

    return (
      <>
        {brandsData?.length ? (
          <div style={{ marginTop: 8, marginBottom: 12 }}>
            <BrandAvatarList
              data={brandsData}
              length={chartData?.labels?.length ?? brandsData.length}
              borderConfig={{ marginLeft: 16, marginRight: 16 }}
              gridConfig={{ paddingLeft: 0, paddingRight: 0 }}
            />
          </div>
        ) : null}
      </>
    );
  }, [chartData]);

  return (
    <StyledWaterfallContainer>
      <StyledChartContainer>
        {shouldShowLegend && (
          <StyledLegendContainer>
            <ChartLegend items={legendItems} />
          </StyledLegendContainer>
        )}
        <Waterfall
          values={chartData?.values || []}
          labels={chartData?.labels || []}
          formattedData={chartData?.formattedData}
          showLabels={false}
          size="large"
          options={{
            animation: false,
            layout: {
              padding: {
                left: 16,
                top: 40,
                bottom: 0,
                right: 16,
              },
            },
            scales: {
              x: {
                display: true,
                border: {
                  display: true,
                  color: '#EDEDED',
                },
                ticks: {
                  display: false,
                },
                grid: {
                  display: false,
                },
              },
            },
            plugins: {
              verticalGuidelines: {
                display: false,
              },
            },
          }}
          colors={WATERFALL_COLORS}
          interactiveConfig={{
            onBarSelect: onBarClick,
            clickability: {
              enabled: true,
              disabledIndexes,
            },
            renderLegend,
            fillHeight: true,
            showTooltip: true,
          }}
          stripedIndexes={chartData?.stripedIndexes || []}
        />
      </StyledChartContainer>

      {chartData?.comparisonLine?.data && (
        <StyledComparisonLineWrapper>
          <ComparisonLine
            data={chartData.comparisonLine.data}
            gridColumnsLength={chartData.labels?.length}
            borderConfig={{ marginLeft: 16, marginRight: 16 }}
            gridConfig={{ paddingLeft: 0, paddingRight: 0 }}
            trendColors={VALUE_CREATION_TREND_COLORS}
            size="medium"
          />
        </StyledComparisonLineWrapper>
      )}
    </StyledWaterfallContainer>
  );
};
